#!/usr/bin/env python
"""Copy docs/results.md (generated by make_report.py) into README.md between the RESULTS markers."""

from __future__ import annotations

import re
import sys
from pathlib import Path


def main() -> int:
    readme = Path("README.md")
    results = Path("docs/results.md")
    if not results.exists():
        print("docs/results.md missing — run scripts/make_report.py first")
        return 1
    body = results.read_text().strip()
    body = re.sub(r"^# Results.*\n", "", body).strip()  # drop the file's own H1
    text = readme.read_text()
    new = re.sub(
        r"<!-- RESULTS:BEGIN -->.*<!-- RESULTS:END -->",
        "<!-- RESULTS:BEGIN -->\n" + body + "\n<!-- RESULTS:END -->",
        text,
        flags=re.S,
    )
    readme.write_text(new)
    print(f"README results section updated ({len(body)} chars)")
    return 0


if __name__ == "__main__":
    sys.exit(main())
